items=[('HOST','Requirements for Internet Hosts — Communication Layers','R. Braden editor','RFC1122 October1989',1989,'https://www.rfc-editor.org/rfc/rfc1122.txt','build/ethernet-wire-sources/rfc1122.txt',['3.3.1–3.3.1.2 printed47–49 local/remote decision, gateway selection and omitted route-cache obligations']),('IP','Internet Protocol','Jon Postel','RFC791 September1981',1981,'https://www.rfc-editor.org/rfc/rfc791.txt','build/network-ip-sources/rfc791.txt',['2.3 printed8–9 fragmentation identity and offsets','3.2 printed24–25,27–29 reassembly representation, example timer and later-arrival overlap policy'])]
resources=[]
for key,title,author,edition,year,url,path,loc in items:
 resources.append(dict(id='R-EH-'+key,title=title,authors=[author],edition=edition,year=year,kind='primary-specification',url=url,access='Actual selected primary passages inspected',domains=['T39','T41'],role='primary',reason='Separate next-hop identity and explicit reassembly policy from broader conformance claims',prerequisites=['Checked C spans and finite Ethernet service'],locators=loc,assignable=True,inspection=dict(date='2026-10-18',method='Actual cached RFC text passages read; source hashes checked, not bibliographic inference',scope=loc,limits='Selected historical passages only; no complete current Internet conformance or independent review claim',capture=dict(path=path,sha256=sha(R/path)))))
